using System.Text.Json;using Microsoft.AspNetCore.Http;
public sealed record McpToolDefinition(string Name,string Description);
public interface IMcpHandler{string ToolName{get;}Task<object> ExecuteAsync(JsonElement arguments,CancellationToken ct=default);}
public sealed class McpToolRouter(IEnumerable<IMcpHandler> handlers){readonly IReadOnlyDictionary<string,IMcpHandler> map=handlers.ToDictionary(x=>x.ToolName,StringComparer.OrdinalIgnoreCase);public IReadOnlyList<McpToolDefinition> List()=>map.Values.Select(x=>new McpToolDefinition(x.ToolName,$"Execute {x.ToolName}")).OrderBy(x=>x.Name).ToArray();public async Task<object> ExecuteAsync(string name,JsonElement args,CancellationToken ct=default){if(!map.TryGetValue(name,out var handler))throw new KeyNotFoundException($"Unknown MCP tool: {name}");if(args.ValueKind is JsonValueKind.Undefined or JsonValueKind.Null||args.GetRawText().Length>32768)throw new ArgumentException("Invalid or oversized arguments",nameof(args));return await handler.ExecuteAsync(args,ct);}}
public abstract class McpHttpHandler(IHttpContextAccessor context){protected async Task<HttpRequestMessage> CreateRequestAsync(HttpMethod method,string url,CancellationToken ct){var request=new HttpRequestMessage(method,url);var http=context.HttpContext;if(http is not null){if(http.Request.Headers.TryGetValue("Authorization",out var auth))request.Headers.TryAddWithoutValidation("Authorization",auth.ToString());if(http.Request.Headers.TryGetValue("X-Tenant-Id",out var tenant))request.Headers.TryAddWithoutValidation("X-Tenant-Id",tenant.ToString());}return await Task.FromResult(request);}}
public sealed class SearchMcpHandler(HttpClient http,IConfiguration config,IHttpContextAccessor context):McpHttpHandler(context),IMcpHandler{public string ToolName=>"document.search";public async Task<object> ExecuteAsync(JsonElement a,CancellationToken ct=default){var query=a.GetProperty("query").GetString()??throw new ArgumentException("query required");var top=a.TryGetProperty("topK",out var k)?k.GetInt32():10;using var req=await CreateRequestAsync(HttpMethod.Post,$"{config["Services:SearchServiceUrl"]!.TrimEnd('/')}/api/v1/search",ct);req.Content=JsonContent.Create(new{query,topK=top});using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();return await res.Content.ReadFromJsonAsync<JsonElement>(cancellationToken:ct);}}
public sealed class DocumentMcpHandler(HttpClient http,IConfiguration config,IHttpContextAccessor context):McpHttpHandler(context),IMcpHandler{public string ToolName=>"document.get";public async Task<object> ExecuteAsync(JsonElement a,CancellationToken ct=default){var id=a.GetProperty("documentId").GetGuid();using var req=await CreateRequestAsync(HttpMethod.Get,$"{config["Services:DocumentServiceUrl"]!.TrimEnd('/')}/api/v1/documents/{id}",ct);using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();return await res.Content.ReadFromJsonAsync<JsonElement>(cancellationToken:ct);}}
public sealed class AuditMcpHandler(HttpClient http,IConfiguration config,IHttpContextAccessor context):McpHttpHandler(context),IMcpHandler{public string ToolName=>"document.audit";public async Task<object> ExecuteAsync(JsonElement a,CancellationToken ct=default){using var req=await CreateRequestAsync(HttpMethod.Get,$"{config["Services:AuditServiceUrl"]!.TrimEnd('/')}/api/v1/audit",ct);using var res=await http.SendAsync(req,ct);res.EnsureSuccessStatusCode();return await res.Content.ReadFromJsonAsync<JsonElement>(cancellationToken:ct);}}